// 1. Get discharge and multiply by 0.5 (scaling factor)
let discharge = ((msg.payload[0] << 16) | msg.payload[1]) * 0.5;

// 2. Get charge and multiply by 0.5
let charge = ((msg.payload[2] << 16) | msg.payload[3]) * 0.5;

// Calculate the values
let batteryPowerW = Math.round(charge - discharge);
let batterySocPct = msg.payload[3]; 

// 3. Save directly to global variables
global.set("battery_power", batteryPowerW);
global.set("battery_soc", batterySocPct);

// 4. SET STATUS ROW UNDER NODE
// Blue when charging (minus), yellow when discharging (plus), green when idle (0W)
let statusColor = "green";
if (batteryPowerW < 0) {
    statusColor = "blue";
} else if (batteryPowerW > 0) {
    statusColor = "yellow";
}

node.status({
    fill: statusColor,
    shape: "dot",
    text: `Power: ${batteryPowerW}W | SoC: ${batterySocPct}%`
});

// 5. Put the values in msg.payload for troubleshooting/debug
msg.payload = {
    battery_power_w: batteryPowerW,
    battery_soc_pct: batterySocPct
};

return msg;

// ==========================================
// 1. READ GLOBAL VARIABLES
// ==========================================
const targetSoC = Number(global.get("sma_soc")) || 50;
const currentSoC = Number(global.get("battery_soc")) || 0;
const forceZeroExport = Number(global.get("zero_export")) || 0;
const housePower = Number(global.get("house_power")) || 0;
const pvPowerA = Number(global.get("pv_string_a")) || 0;
const pvPowerB = Number(global.get("pv_string_b")) || 0;
const pvPower = pvPowerA + pvPowerB;
const grid_import = Number(global.get("grid_import"));
const charge_power = Math.min((Number(global.get("charge_power")) || 5) * 1000, 9000);

let currentState = context.get("currentState") || "AUTO";


// ==========================================
// 2. STATE MACHINE
// ==========================================
let newState = currentState;
const hasSolarSurplus = pvPower > (housePower + 50);

if (forceZeroExport === 1) {
    newState = "ZERO_EXPORT";
} else if (targetSoC > currentSoC) {
    newState = "CHARGE";
} else if (currentSoC > targetSoC) {
    newState = "AUTO";
} else if (currentSoC === targetSoC) {
    if (hasSolarSurplus && currentSoC < 100) {
        newState = "AUTO";
    } else {
        newState = "LOCKED";
    }
}

if (newState !== currentState) {
    context.set("currentState", newState);
    currentState = newState;
    node.warn(`🔄 Switching operating mode to: ${currentState}`);
}

// ==========================================
// 3. PARAMETERS & ICONS FOR STATE
// ==========================================
let mode = 803;          
let powerLimit = 100;    
let activePower = 0;     
let activeReason = "";

switch (currentState) {
    case "ZERO_EXPORT":
        mode = 802;
        activePower = 0; 
        let limit = Math.min(Math.round((housePower / 8000) * 100), 100);
        powerLimit = limit < 0 ? 0 : limit;
        activeReason = `🚫 (${powerLimit}%)`;
        break;

    case "CHARGE":
        mode = 802;
        let avail = 12400 - housePower + pvPower; // 20A*3F*230V=13800W -> 12400 with some margins
        if (avail > charge_power) { // 9kW max charge although SMA manage 10kW
            avail = charge_power;
        }
        activePower = avail * -1; // charge battery with minus 
        powerLimit = 100;    
        activeReason = "⚡ ";
        break;

    case "LOCKED":
        mode = 802;
        activePower = 0;     
        powerLimit = 100;    
        activeReason = "🔒 ";
        break;

    case "AUTO":
    default:
        mode = 803;
        activePower = 0;
        powerLimit = 100;
        activeReason = "⚖️ ";
        break;
}

// ==========================================
// 4. FORMAT FOR MODBUS WRITE
// ==========================================
let msgsToModbus = [];
function getS32Array(value) {
    let buf = Buffer.alloc(4);
    buf.writeInt32BE(Math.round(value));
    return [buf.readUInt16BE(0), buf.readUInt16BE(2)];
}
function getS16Value(value) {
    let intVal = Math.round(value);
    return intVal < 0 ? 65536 + intVal : intVal; 
}

// Add the Modbus writes to the queue (positions 1, 2, and 3)
msgsToModbus.push({ payload: [0, mode], address: "40151", unique_id: "sma_mode_40151" });
msgsToModbus.push({ payload: [getS16Value(powerLimit)], address: "40016", unique_id: "sma_limit_40016" });
msgsToModbus.push({ payload: getS32Array(activePower), address: "40149", unique_id: "sma_power_40149" });

// ==========================================
// 5. STATUS UPDATE & SMART DISPATCH
// ==========================================
const statusColor = { "ZERO_EXPORT": "red", "CHARGE": "blue", "LOCKED": "yellow", "AUTO": "green" }[currentState];

node.status({
    fill: statusColor,
    shape: "dot",
    text: `[${currentState}] ${activeReason} | PV: ${pvPower}W | House: ${housePower}W | SoC: ${currentSoC}% | Target: ${targetSoC}% | Charge: ${charge_power / 1000}kW`
});

// LOGIC: 
// 1. If in AUTO: Send only on change or every 10 seconds (to save writes).
// 2. If in any other mode: Always send (every second) to guarantee control.

let now = Date.now();
let lastSentTime = context.get("lastSentTime") || 0;
let stateChanged = (currentState !== context.get("lastSentState"));
let timeToResendAuto = (currentState === "AUTO" && (now - lastSentTime) > 60000);
let isForcedMode = (currentState !== "AUTO"); // CHARGE, LOCKED, ZERO_EXPORT

if (stateChanged || isForcedMode || timeToResendAuto) {
    let delayMs = 0;

    // --- ADD THE MQTT MESSAGE AT THE VERY END OF THE QUEUE ---
    // Since we push it last, it ends up after the Modbus messages
    // and is sent as the absolute last packet out of the node.
    if (stateChanged) {
        msgsToModbus.push({
            payload: currentState,
            address: "MQTT_STATE",
            topic: "sma/state",
            unique_id: "sma_mqtt_state_update"
        });
    }
    // ---------------------------------------------------

    // Loop through and send the packets one by one
    msgsToModbus.forEach((m) => {
        setTimeout(() => {
            let outMsg = Object.assign({}, msg);
            outMsg.payload = m.payload;
            outMsg.address = m.address;
            outMsg.unique_id = m.unique_id;

            // If there is a topic (like for the MQTT packet), include it
            if (m.topic) {
                outMsg.topic = m.topic; 
            }

            node.send(outMsg);
        }, delayMs);

        // Increase the delay by 250ms for the next packet in the queue
        delayMs += 250;
    });

    // Update timestamp and state
    context.set("lastSentTime", now);
    context.set("lastSentState", currentState);
}

return null;

// 1. Save incoming value per phase in the node's INTERNAL memory (context)
if (msg.topic === "shellies/shellyem3/emeter/0/power") {
    context.set("em3_p0", Number(msg.payload) || 0);
} 
else if (msg.topic === "shellies/shellyem3/emeter/1/power") {
    context.set("em3_p1", Number(msg.payload) || 0);
} 
else if (msg.topic === "shellies/shellyem3/emeter/2/power") {
    context.set("em3_p2", Number(msg.payload) || 0);
}

// 2. Get the last known values
let p0 = context.get("em3_p0") || 0;
let p1 = context.get("em3_p1") || 0;
let p2 = context.get("em3_p2") || 0;

// 3. Calculate the total
let totalHousePower = Math.round(p0 + p1 + p2);

// ==========================================
// 4. RATE LIMITER
// ==========================================
const RATE_LIMIT_MS = 1000; // Allow an update at most every 1000 milliseconds (1 second)

let lastSave = context.get("lastSaveTime") || 0;
let now = Date.now();

// Has enough time passed since the last update?
if (now - lastSave >= RATE_LIMIT_MS) {

    // Save the total to global memory so the State Machine can use it
    global.set("house_power", totalHousePower);

    // Update the clock
    context.set("lastSaveTime", now);

    // Clean up the number and pass it forward for debug/display
    msg.payload = Math.round(totalHousePower);

    // Show in Node-RED's interface when it last updated
    let timeString = new Date().toLocaleTimeString();
    node.status({ fill: "green", shape: "dot", text: `${msg.payload} W (Last: ${timeString})` });

    return msg;

} else {
    // Too little time has passed. We abort the flow here so the rest of the 
    // system (or your debug node) is not triggered unnecessarily.
    return null;
}

/**
 * SMA NET GRID POWER COMBINER
 * Combines TotWIn (30865) and TotWOut (30867) into a single value
 */

let data = msg.payload;

if (Array.isArray(data) && data.length === 4) {
    // 1. Unpack Import (30865-30866)
    let bufIn = Buffer.alloc(4);
    bufIn.writeUInt16BE(data[0], 0);
    bufIn.writeUInt16BE(data[1], 2);
    let importPower = bufIn.readInt32BE(0);

    // 2. Unpack Export (30867-30868)
    let bufOut = Buffer.alloc(4);
    bufOut.writeUInt16BE(data[2], 0);
    bufOut.writeUInt16BE(data[3], 2);
    let exportPower = bufOut.readInt32BE(0);

    // 3. Logic: Create a common value
    let netGridPower = 0;

    if (importPower > 0) {
        // Buying electricity - positive value
        netGridPower = importPower;
    } 
    else if (exportPower > 0) {
        // Selling electricity - convert to negative value
        netGridPower = exportPower * -1;
    }

    // Save the value globally
    global.set("grid_import", netGridPower);

    // Pass forward for debug
    msg.payload = netGridPower;

    // Status below the node for a quick check
    let statusColor = netGridPower > 0 ? "yellow" : "green";
    node.status({fill: statusColor, shape:"dot", text: "Grid: " + netGridPower + " W"});

} else {
    node.status({fill:"red", shape:"ring", text: "Waiting for 4 registers..."});
}

return msg;

if (Array.isArray(msg.payload) && msg.payload.length >= 2) {
    let buf = Buffer.alloc(4);
    buf.writeUInt16BE(msg.payload[0], 0);
    buf.writeUInt16BE(msg.payload[1], 2);
    let val = buf.readInt32BE(0);

    // Protection against night ghost values (-W)
    global.set("pv_string_a", val < 0 ? 0 : val); 
    node.status({fill:"green",shape:"dot",text:"PV: "+ val + "W"});
}

return msg; // We do not need to pass the data forward, it is saved globally

if (Array.isArray(msg.payload) && msg.payload.length >= 2) {
    let buf = Buffer.alloc(4);
    buf.writeUInt16BE(msg.payload[0], 0);
    buf.writeUInt16BE(msg.payload[1], 2);
    let val = buf.readInt32BE(0);

    global.set("pv_string_b", val < 0 ? 0 : val); 
    node.status({fill:"green",shape:"dot",text:"PV: "+ val + "W"});
}
return msg;
